class Behavior{
 class Setting<T>{public T Value{get;set;}}
 class RegenSettings{public static Setting<bool> modEnabled=new Setting<bool>{Value=true};public static Setting<float> healthRegenMult=new Setting<float>{Value=2},healthRegenTimeMult=new Setting<float>{Value=0.5f};}
 static int count;static void Check(bool b,string s){if(!b)throw new Exception("FAIL "+s);count++;Console.WriteLine("PASS "+s);}
 static T Make<T>(int id,string prefab)where T:Character,new(){var go=new GameObject();var c=new T();go.Add(c);go.Add(new ZNetView{Zdo=new ZDO{m_uid=new ZDOID{Value=id},Prefab=Travel.StableHash(prefab)}});c.Manager=new SEMan{m_character=c};Character.All.Add(c);ZNetScene.instance.Objects[c.GetZDOID()]=go;return c;}
 static Character Skeleton(int id,Player p){var c=Make<Character>(id,"Skeleton_Friendly");c.gameObject.Add(new Tameable());c.gameObject.Add(new MonsterAI{Target=p.gameObject});return c;}
 static void Shield(Character c,float time=12,float damage=37){c.Manager.Effects.Add(new SE_Shield{Hash=123,m_ttl=120,m_time=time,m_totalAbsorbDamage=450,m_damage=damage,m_character=c});ObjectDB.instance.Templates[123]=new SE_Shield{Hash=123,m_ttl=120};}
 static void Step(){Time.frameCount++;Travel.Tick();}
 static void Complete(Player p){Time.frameCount++;Travel.CompleteLocal(p);}
 static bool Landing(Player p,Character c,int i,out Vector3 v,float clearance=1f,bool retreat=false){Time.frameCount++;return Travel.FindLanding(p,c,i,out v,clearance,retreat);}
 static FakeHudData Head(Character c){var gui=new GameObject{name="HeadHud",transform=new RectTransform()};var name=new GameObject{name="Name",transform=new RectTransform()};name.transform.parent=gui.transform;var text=new FakeText{text="원래 이름",fontSize=18};name.Add(text);var health=new GameObject{name="Health",transform=new RectTransform()};health.transform.parent=gui.transform;var data=new FakeHudData{m_character=c,m_gui=gui,m_name=text};int i=0;foreach(var n in new[]{"health_fast","health_slow","health_fast_friendly"}){var go=new GameObject{name=n,transform=new RectTransform()};go.transform.parent=health.transform;var bar=new FakeGuiBar();go.Add(bar);go.Add(new UnityEngine.UI.Image());if(i==0)data.m_healthFast=bar;else if(i==1)data.m_healthSlow=bar;else data.m_healthFastFriendly=bar;i++;}return data;}
 static GameObject Gear(string name,Skills.SkillType skill,ItemDrop.ItemData.ItemType type){var go=new GameObject{name=name};go.Add(new ItemDrop{m_itemData=new ItemDrop.ItemData{m_shared=new ItemDrop.SharedData{m_skillType=skill,m_itemType=type}}});go.GetComponent<ItemDrop>().m_itemData.m_dropPrefab=go;return go;}
 static int summonId=80000;static Humanoid FreshSkeleton(GameObject[] weapons,GameObject shield){var h=Make<Humanoid>(summonId++,"Skeleton_Friendly");h.gameObject.name="Skeleton_Friendly(Clone)";h.gameObject.Add(new Tameable());h.gameObject.Add(new MonsterAI());h.m_randomWeapon=weapons;h.m_randomShield=new[]{shield};return h;}
 static SpawnAbility Raiser(Player owner,GameObject[] weapons,GameObject shield){var go=new GameObject{name="staff_skeleton_aoe(Clone)"};var a=new SpawnAbility{m_spawnPrefab=new[]{new GameObject{name="Skeleton_Friendly"}},m_maxSpawned=0,AwakeCallback=SpawnRoster.Mark,EquipmentCallback=SpawnRoster.Apply,Factory=()=>FreshSkeleton(weapons,shield)};go.Add(a);a.m_levelUpSettings.Add(new SpawnAbility.LevelUpSettings{m_skill=Skills.SkillType.BloodMagic,m_skillLevel=0,m_maxSpawns=2});a.m_levelUpSettings.Add(new SpawnAbility.LevelUpSettings{m_skill=Skills.SkillType.BloodMagic,m_skillLevel=25,m_maxSpawns=3});a.m_levelUpSettings.Add(new SpawnAbility.LevelUpSettings{m_skill=Skills.SkillType.BloodMagic,m_skillLevel=75,m_maxSpawns=4});return a;}
